function CheckC76($name,[byte[]]$expected,[byte[]]$actual,[switch]$Mismatch){Check75 $name (Bytes75 ([Convert]::ToBase64String($expected))) (Bytes75 ([Convert]::ToBase64String($actual))) -Mismatch:$Mismatch}
function LongCheckC76($name,[byte[]]$expected,[byte[]]$actual){
 if($expected.Length -ne $actual.Length){throw ('Long count framing '+$name)};$a=Bytes75 ([Convert]::ToBase64String($expected));$b=Bytes75 ([Convert]::ToBase64String($actual))
 for($outer=0;$outer -lt $a.Length;$outer+=50000){$count=[Math]::Min(50000,$a.Length-$outer);$blocks=[Collections.Generic.List[byte[]]]::new();for($offset=0;$offset -lt $count;$offset+=200){$n=[Math]::Min(200,$count-$offset);$blocks.Add((Join75 @((Bytes75 $n.ToString('000')),(Slice75 $a ($outer+$offset) $n),(Slice75 $b ($outer+$offset) $n))))};$payload=Join75 @((Bytes75 $blocks.Count.ToString('000')),(Join75 $blocks.ToArray()));$result=Run75 'training/compat32-v11/verify-long.bf' $payload;$required=Join75 @((Bytes75 ('0'*$blocks.Count)),([byte[]]@(0)));CheckC76 ($name+'/'+$outer) $required $result}
}
function CounterBoundariesC76(){
 $zero=[byte[]]::new(42);$zero[41]=49;$read=[byte[]]$zero.Clone();$read[0]=255;$increment=[byte[]]$zero.Clone();$increment[3]=1;$copyHigh=[byte[]]$increment.Clone();$copyHigh[30]=1;$divideHigh=[byte[]]$increment.Clone();$divideHigh[32]=1
 $states=@(@{Name='read-word';Output='';Tape=$read},@{Name='increment';Output='';Tape=$increment},@{Name='copy-high';Output='';Tape=$copyHigh},@{Name='divide-high';Output='';Tape=$divideHigh},@{Name='emit-high';Output='AB';Tape=$increment},@{Name='copy-low';Output='AB';Tape=$increment},@{Name='divide-low';Output='AB';Tape=$increment},@{Name='emit-low';Output='ABAA';Tape=$increment},@{Name='emit-flag';Output='ABAA0';Tape=$zero})
 $refRead=[byte[]]$zero.Clone();$refRead[0]=65;$refRead[1]=65;$refRead[2]=80;$refRead[3]=80;$refIncrement=[byte[]]$zero.Clone();$refIncrement[0]=65;$refIncrement[1]=66;$refIncrement[2]=65;$refIncrement[3]=65
 $states+=@(@{Name='reference-read';Output='';Tape=$refRead},@{Name='reference-increment';Output='';Tape=$refIncrement},@{Name='reference-emit';Output='ABAA0';Tape=$zero})
 foreach($state in $states){$expected=Join75 @((Bytes75 $state.Output),$state.Tape);CheckC76 ('count boundary '+$state.Name) $expected (Run75 ("training/freqcount32-v1/"+$state.Name+'-clean.probe.bf') (Bytes75 'AAPP'));foreach($damage in 'drift','dirty'){CheckC76 ('count bad boundary '+$state.Name+'/'+$damage) $expected (Run75 ("training/freqcount32-v1/"+$state.Name+'-'+$damage+'.probe.bf') (Bytes75 'AAPP')) -Mismatch}}
 foreach($route in 'increment','reference'){CheckC76 ('counter entry scratch '+$route) (Join75 @((Bytes75 'ABAA0'),$zero)) (Run75 ("training/freqcount32-v1/$route-entry-dirty.probe.bf") (Bytes75 'AAPP')) -Mismatch}
 $overflow=[byte[]]$zero.Clone();$overflow[1]=1;CheckC76 'raw16 overflow flag' $overflow (Run75 'training/freqcount32-v1/increment-clean.probe.bf' (Bytes75 'PPPP'))
}
